object LanguageWorker{def main(args:Array[String]):Unit={val key=0x4f;var s=scala.io.StdIn.readLine();while(s!=null){if(s=="PING"){println("PONG");Console.flush()}else if(s=="QUIT")return else if(s.matches("^[ED] [0-9A-Fa-f]*$")){val h=s.substring(2);val o=(0 until h.length by 2).map(i=>f"${Integer.parseInt(h.substring(i,i+2),16)^key}%02x").mkString;println(o);Console.flush()}else{println("ERR");Console.flush()};s=scala.io.StdIn.readLine()}}}
